using UnityEngine;

public sealed partial class DefenseGame {
 GUIStyle civHero,civHeading,civBody,civCaption,civSmall,civButton,civNumber;static readonly Color civInk=new Color(.89f,.95f,1),civMuted=new Color(.47f,.62f,.72f),civCyan=new Color(.24f,.94f,.79f),civAmber=new Color(1,.63f,.25f),civPanel=new Color(.025f,.055f,.083f,1);
 string[] civTabs={"OVERVIEW","ORACLE / MISSIONS","CITY PLANNER","SHIPWRIGHT","FLEET COMMAND","DYSON PROJECT"};
 public bool CivilUIOpen{get{return civilOpen||civilRecord||VoyagerMenuOpen;}}
 public Vector3 CivilStarPosition(int system){return catalog[Mathf.Clamp(system,0,catalog.Count-1)].location+new Vector3(-20000,10000,-75000)-OriginGlobal;}
 void CivilStyles(){if(civBody!=null)return;civBody=new GUIStyle(GUI.skin.label){fontSize=22,wordWrap=true,normal={textColor=Color.white}};civHeading=new GUIStyle(civBody){fontSize=33,fontStyle=FontStyle.Bold};civHero=new GUIStyle(civHeading){fontSize=45};civCaption=new GUIStyle(civBody){fontSize=17,normal={textColor=Color.white}};civSmall=new GUIStyle(civCaption){fontSize=15};civNumber=new GUIStyle(civBody){fontSize=30,fontStyle=FontStyle.Bold};civButton=new GUIStyle(GUI.skin.label){fontSize=19,fontStyle=FontStyle.Bold,wordWrap=true,alignment=TextAnchor.MiddleCenter,normal={textColor=Color.white}};}
 void CBox(Rect r,Color color){GUI.color=color.linear;GUI.DrawTexture(r,Texture2D.whiteTexture);GUI.color=Color.white;}
 void CText(Rect r,string value,GUIStyle style=null,Color? color=null){GUI.color=(color??(style==civCaption||style==civSmall?civMuted:civInk)).linear;GUI.Label(r,ControlHints(value),style??civBody);GUI.color=Color.white;}
 bool CButton(Rect r,string value,bool active=false){bool hover=r.Contains(Event.current.mousePosition)&&!automatedPlayback;CBox(r,active?new Color(.055f,.26f,.26f):hover?new Color(.065f,.15f,.20f):new Color(.035f,.08f,.115f));if(active)CBox(new Rect(r.x,r.y,3,r.height),civCyan);bool hit=GameButton(r,"",GUIStyle.none);CText(r,value,civButton,active?civCyan:civInk);return hit;}
 void CBar(Rect r,float value,Color color){CBox(r,new Color(.09f,.16f,.21f));CBox(new Rect(r.x,r.y,r.width*Mathf.Clamp01(value),r.height),color);}
 void ChangeCivilTab(int tab){civilTab=tab;civilSelection=0;civilizationScene.Preview(civilTab,civilSelection,civilPaint,civilization);}
 void CWallet(float x,float w,string title,string value,string detail){CBox(new Rect(x,196,w,73),civPanel);CText(new Rect(x+16,202,w*.55f-16,22),title,civSmall);CText(new Rect(x+w*.58f,202,w*.4f-8,28),detail,civSmall);CText(new Rect(x+16,225,w-24,39),value,value.Length>10?civBody:civNumber);}
 bool DrawCivilization(){if(civilization==null||!civilOpen)return false;CivilStyles();CBox(new Rect(0,0,1600,1000),new Color(.012f,.027f,.043f));CBox(new Rect(45,42,5,66),civCyan);CText(new Rect(67,37,1050,55),"WAYFARER  /  NEW DAWN",civHero);CText(new Rect(69,96,1060,27),"YOUR SHIP. YOUR WORLDS. YOUR CIVILIZATION.",civCaption);
  if(CButton(new Rect(1278,58,272,49),"RESUME  /  CIRCLE"))CloseCivilization();for(int i=0;i<6;i++){float x=50+i*251;bool selected=civilTab==i;if(CButton(new Rect(x,140,242,42),civTabs[i],selected))ChangeCivilTab(i);if(selected)CBox(new Rect(x,183,242,3),civCyan);}
  CWallet(50,265,"REFINED ALLOY",civilization.alloy.ToString("N0"),"+"+(civilization.Count(2)*1.8f).ToString("F1")+" / s");CWallet(330,265,"STORED ENERGY",civilization.energy.ToString("N0"),civilization.PowerRate.ToString("+0.0;-0.0;0")+" / s");CWallet(610,265,"SCIENCE",civilization.science.ToString("N0"),"+"+(civilization.Count(4)*.48f).ToString("F2")+" / s");CWallet(890,275,"CIVILIZATION",civilization.LevelName,"TIER "+civilization.Level);CWallet(1180,370,"YOUR PEOPLE",civilization.Population.ToString("N0"),civilization.colonies.Count+" worlds / "+civilization.fleet+" ships");
  CBox(new Rect(919,293,631,412),new Color(.018f,.039f,.059f));GUI.DrawTexture(new Rect(925,294,620,405),civilizationScene.PreviewTexture,ScaleMode.ScaleToFit,false);CText(new Rect(940,307,590,28),civilTab==2?"CONSTRUCTION / LIVE 3D BLUEPRINT":civilTab==5?"STELLAR ENGINEERING / COLLECTOR SHELL":"SHIPWRIGHT / LIVE 3D DESIGN",civSmall);
  if(civilTab==0)DrawCivilOverview();else if(civilTab==1)DrawCivilOracle();else if(civilTab==2)DrawCivilCity();else if(civilTab==3)DrawCivilShips();else if(civilTab==4)DrawCivilFleets();else DrawCivilDyson();
  CBox(new Rect(50,955,1500,1),new Color(.12f,.22f,.29f));CText(new Rect(52,969,1480,27),"B / L3 in flight / D-pad down on foot: command   •   L1/R1: tabs   •   D-pad: select   •   Cross: act   •   Circle: resume",civSmall);
  if(civilRecord)CText(new Rect(700,96,840,30),"RECORDED SHOWCASE / SEEDED RESOURCES",civSmall,civAmber);else if(noticeTime>0){CBox(new Rect(700,88,847,38),new Color(.08f,.18f,.20f));CText(new Rect(712,95,817,29),notice,civCaption,civCyan);}return true;
 }
 void DrawCivilOverview(){CText(new Rect(53,295,830,110),civilization.Level==0?"A new frontier starts with you.":"The age of "+civilization.LevelName.ToLower()+".",civHero);CText(new Rect(56,421,810,79),"Land, establish a city, and turn resources into research, rockets and an interplanetary civilization.",civBody,civMuted);
  var goals=civilization.Recommendations();if(goals.Count>0){var goal=goals[0];CBox(new Rect(55,525,810,170),civPanel);CText(new Rect(76,542,760,25),"ORACLE RECOMMENDS",civCaption,civCyan);CText(new Rect(75,575,760,43),goal.title,civHeading);CText(new Rect(77,625,758,58),goal.why,civCaption);}
  string next=civilization.Level==0?"FOUNDATION / complete a command spire":civilization.Level==1?"PLANETARY / observatory + a successful rocket launch":civilization.Level==2?"INTERPLANETARY / establish or liberate a second world":civilization.Level==3?"STELLAR / complete four Dyson sectors":civilization.Level==4?"TYPE II / finish all twelve collector sectors":"STELLAR CIVILIZATION / expand, explore and defend";CText(new Rect(59,739,805,63),"NEXT AGE\n"+next,civCaption);
  if(CButton(new Rect(56,845,384,50),"ORACLE / FIND A MISSION",true))ChangeCivilTab(1);if(CButton(new Rect(455,845,410,50),"CITY PLANNER"))ChangeCivilTab(2);
  CText(new Rect(940,728,580,82),CivilizationModel.HullNames[civilization.blueprint],civHeading);CText(new Rect(942,819,580,64),"Survey launches "+civilization.launches+"   /   wars won "+civilization.warsWon+"\nProgress saves automatically on this Mac.",civCaption);
  if(CButton(new Rect(941,892,581,44),civilization.Level==0?"BEGIN / VTOL DESCENT TO PELAGOS":"RETURN TO EXPLORATION",true))BeginCivilExploration();
 }
 void DrawCivilOracle(){var goals=civilization.Recommendations();CText(new Rect(55,296,810,45),"A direction, chosen for your world.",civHeading);if(goals.Count==0){CText(new Rect(60,390,760,140),"Every major milestone is complete. Your civilization is ready for free exploration and expansion.");return;}civilSelection=Mathf.Clamp(civilSelection,0,goals.Count-1);
  for(int i=0;i<goals.Count;i++){var g=goals[i];Rect r=new Rect(55,363+i*58,810,51);CBox(r,i==civilSelection?new Color(.065f,.18f,.21f):civPanel);if(CButton(new Rect(r.x,r.y,810,51),(civilization.activeGoal==g.id?"ACTIVE  /  ":"")+g.title,i==civilSelection)){civilSelection=i;}CBar(new Rect(r.x+12,r.y+46,786,2),g.progress,civCyan);}
  var goal=goals[civilSelection];CText(new Rect(941,724,580,53),goal.title,civHeading);CText(new Rect(942,786,577,84),goal.why,civCaption);CText(new Rect(942,863,577,30),"REWARD / "+goal.rewardOre+" alloy + "+goal.rewardScience+" science",civCaption,civAmber);if(CButton(new Rect(941,902,580,42),goal.progress>=.999f?"CROSS / CLAIM MILESTONE REWARD":civilization.activeGoal==goal.id?"ACTIVE / FOLLOW YOUR OBJECTIVE":"CROSS / ACCEPT RECOMMENDATION",true))CivilPrimary();
 }
 void DrawCivilCity(){CText(new Rect(55,296,810,43),"Cities grow from the ground up.",civHeading);var colony=CivilLocal;for(int i=0;i<8;i++){Rect r=new Rect(55,354+i*57,810,51);bool selected=i==civilSelection;CBox(r,selected?new Color(.065f,.18f,.21f):civPanel);if(CButton(new Rect(r.x,r.y,810,51),CivilizationModel.DistrictNames[i]+"    /    "+CivilizationModel.OreCost[i]+" A  "+CivilizationModel.EnergyCost[i]+" E  "+CivilizationModel.ScienceCost[i]+" S",selected)){civilSelection=i;civilizationScene.Preview(2,i,civilPaint,civilization);}}
  CText(new Rect(941,724,580,49),CivilizationModel.DistrictNames[civilSelection],civHeading);CText(new Rect(942,784,577,84),CivilizationModel.DistrictDescriptions[civilSelection],civCaption);CText(new Rect(942,864,577,28),"CONSTRUCTION / "+CivilizationModel.BuildSeconds[civilSelection]+" seconds",civCaption,civAmber);if(CButton(new Rect(941,902,580,42),"CROSS / PLACE ON THE SURFACE",true))CivilPrimary();
  if(civilSelection==5){if(CButton(new Rect(55,840,393,51),"TRIANGLE / ASSEMBLE ROCKET"))CivilSecondary();if(CButton(new Rect(465,840,400,51),"SQUARE / LAUNCH  ("+(colony==null?0:colony.rockets)+" READY)",true))LaunchCivilRocket();CText(new Rect(58,900,800,32),colony!=null&&colony.fabricating?"Assembly "+(colony.rocketWork*100).ToString("F0")+"% / resume the world to progress":"Assembly costs 90 alloy / 60 energy / 12 science",civCaption);}
  else if(civilSelection==6){if(CButton(new Rect(55,848,810,51),"TRIANGLE / FABRICATE A WARSHIP"))CivilSecondary();}
  else CText(new Rect(58,840,798,84),GroundActive?"Aim a clear foundation. E / R1 confirms. Q / R rotates. Circle cancels. Production advances while exploring.":"Land and leave the craft before placing districts. Your colony remains on this planet when you travel.",civCaption);
 }
 void DrawCivilShips(){CText(new Rect(55,296,810,44),"Design a ship that is yours.",civHeading);for(int i=0;i<4;i++){bool owned=(civilization.ownedHulls&(1<<i))!=0;Rect r=new Rect(55,365+i*91,810,77);CBox(r,i==civilSelection?new Color(.065f,.18f,.21f):civPanel);if(CButton(new Rect(r.x,r.y,r.width,77),CivilizationModel.HullNames[i]+"\n"+(owned?"BLUEPRINT OWNED":CivilizationModel.HullOre[i]+" ALLOY / "+CivilizationModel.HullScience[i]+" SCIENCE"),i==civilSelection)){civilSelection=i;civilizationScene.Preview(3,i,civilPaint,civilization);}}
  CText(new Rect(60,767,760,37),"COATING / SQUARE OR C TO CYCLE",civCaption);string[] names={"GLACIER","ABYSS","EMBER","NEBULA"};for(int i=0;i<4;i++){CBox(new Rect(60+i*200,816,181,40),FrontierArt.Paints[i]);if(CButton(new Rect(60+i*200,862,181,37),names[i],civilPaint==i)){civilPaint=i;civilizationScene.Preview(3,civilSelection,civilPaint,civilization);}}
  CText(new Rect(941,722,580,45),CivilizationModel.HullNames[civilSelection],civHeading);CText(new Rect(942,781,577,100),CivilizationModel.HullDescriptions[civilSelection],civCaption);if(CButton(new Rect(941,902,580,42),"CROSS / RESEARCH & EQUIP DESIGN",true))CivilPrimary();
 }
 void DrawCivilFleets(){CText(new Rect(55,296,810,44),"Other worlds have ambitions too.",civHeading);for(int i=0;i<3;i++){var f=civilization.factions[i];Rect r=new Rect(55,364+i*106,810,93);CBox(r,civilSelection==i?new Color(.065f,.18f,.21f):civPanel);if(CButton(new Rect(r.x,r.y,r.width,r.height),f.name+"   /   "+f.species+"\nRELATIONS "+f.relation+"   /   "+f.strength+" WARSHIPS",civilSelection==i)){civilSelection=i;civilizationScene.Preview(4,i,civilPaint,civilization);}}
  if(CButton(new Rect(55,695,810,63),"RESERVE / "+civilization.fleet+" WARSHIPS  /  BUILD ONE",civilSelection==3))civilSelection=3;
  var front=civilization.wars.Find(w=>!w.resolved);CText(new Rect(60,790,793,69),front==null?"No active fronts. Send an envoy to improve relations or dispatch a fleet of at least three ships.":(front.raid?"INCOMING RAID":"ACTIVE WAR")+" / "+civilization.factions[front.enemy].name+"\n"+(front.travel>0?"Warp transit / "+front.travel.ToString("F0")+"s":"Orbital combat / "+CivilizationModel.Living(front.friendly)+" allied vs "+CivilizationModel.Living(front.hostile)+" hostile"),civCaption);
  if(front!=null){if(CButton(new Rect(55,884,810,48),"SQUARE / SET COURSE TO ORBITAL FRONT",true))CivilNavigateWar();}else if(civilSelection<3&&CButton(new Rect(55,884,810,48),"SQUARE / VISIT THIS CIVILIZATION"))CivilNavigateFaction(civilSelection);
  CText(new Rect(941,725,580,44),civilSelection==3?"Orbital fleet reserve":civilization.factions[civilSelection].name,civHeading);CText(new Rect(942,788,577,51),civilSelection==3?"Build warships at your orbital shipyard. A strike deploys up to six ships. Survivors return to reserve.":"Fleet wars continue between worlds. Join the front and destroy hostile ships yourself, or use diplomacy to prevent future raids.",civCaption);
  if(CButton(new Rect(940,889,580,43),civilSelection==3?"CROSS / BUILD SHIP: 95 A / 40 E / 15 S":"CROSS / DISPATCH PLANETARY FLEET",true))CivilPrimary();if(civilSelection<3&&CButton(new Rect(941,838,580,39),"TRIANGLE / SEND ENVOY: 75 A / 35 E / 10 S"))CivilSecondary();
 }
 void DrawCivilDyson(){CText(new Rect(54,297,810,110),"Build a civilization powered by a star.",civHero);CText(new Rect(58,424,795,88),"Autonomous collectors assemble into twelve stellar sectors. Each completed sector supplies power to every colony.",civBody,civMuted);
  CText(new Rect(59,548,800,50),civilization.dysonBuilt+" / 12 SECTORS   •   "+civilization.dysonBuilt*56+" COLLECTORS",civHeading);for(int i=0;i<12;i++){float x=61+i*66;CBox(new Rect(x,619,54,85),i<civilization.dysonBuilt?new Color(.08f,.55f,.48f):civPanel);if(i==civilization.dysonBuilt&&civilization.dysonWorking)CBar(new Rect(x,619,54,85),civilization.dysonWork,civAmber);CText(new Rect(x+15,648,45,30),(i+1).ToString("D2"),civCaption);}
  CText(new Rect(60,752,795,97),"STELLAR OUTPUT / +"+civilization.dysonBuilt*22+" ENERGY PER SECOND\nRequires interplanetary civilization + orbital shipyard. Complete all sectors to reach Type II.",civCaption);
  if(CButton(new Rect(56,884,810,49),"TRIANGLE / SET COURSE TO STELLAR PROJECT"))CivilNavigateStar();CText(new Rect(941,725,580,48),civilization.dysonBuilt==12?"TYPE II / A NEW AGE":"DYSON / COLLECTOR SECTOR "+(civilization.dysonBuilt+1),civHeading);CText(new Rect(943,788,575,80),civilization.dysonWorking?"Sector assembly "+(civilization.dysonWork*100).ToString("F0")+"%. Resume the world to continue construction.":"Next sector: "+(260+civilization.dysonBuilt*20)+" alloy / 160 energy / 75 science. Construction takes 24 seconds.",civCaption);if(CButton(new Rect(941,902,580,42),"CROSS / CONSTRUCT COLLECTOR SECTOR",true))CivilPrimary();
 }
 void DrawCivilFilmHUD(){CivilStyles();CBox(new Rect(0,0,1600,110),new Color(.01f,.025f,.04f,.9f));CText(new Rect(43,23,1050,45),"NEW DAWN / "+civilFilmChapter,civHeading);CText(new Rect(45,77,1100,28),civilization.LevelName+"  /  "+civilization.colonies.Count+" WORLDS  /  "+civilization.Population.ToString("F0")+" CITIZENS  /  "+civilization.dysonBuilt+" DYSON SECTORS",civCaption,civCyan);CBox(new Rect(0,953,1600,47),new Color(.01f,.025f,.04f,.9f));CText(new Rect(44,966,1500,28),"RECORDED UNITY GAMEPLAY / STAGED SHOWCASE WITH SEEDED RESOURCES / SCRIPTED INPUT",civSmall,civAmber);DrawCivilWar();}
 void DrawCivilHUD(){if(civilization==null)return;CivilStyles();if(civilRecord&&!civilOpen)CText(new Rect(465,104,800,40),"STAGED CIVILIZATION SHOWCASE / SEEDED RESOURCES",civCaption,civAmber);if(!civilOpen&&!paused&&!chartOpen&&!upgradeOpen&&!HelmetPhotoUI.BlocksControls&&outcome==""){CBox(new Rect(43,684,360,113),new Color(.015f,.045f,.065f,.94f));CText(new Rect(57,695,340,27),civilization.LevelName+" / TIER "+civilization.Level,civCaption,civCyan);CText(new Rect(57,728,340,26),"A "+civilization.alloy.ToString("F0")+"   E "+civilization.energy.ToString("F0")+"   S "+civilization.science.ToString("F0"),civCaption);CText(new Rect(57,764,339,25),GroundActive?"B / D-PAD DOWN : COMMAND":"B / L3 : CIVILIZATION COMMAND",civSmall);DrawCivilWar();}
  if(civilPlacing){CBox(new Rect(440,665,750,109),new Color(.02f,.08f,.10f,.96f));CText(new Rect(461,675,715,33),"FOUNDATION / "+CivilizationModel.DistrictNames[civilPlaceKind],civBody,civilPlaceValid?civCyan:civAmber);CText(new Rect(462,713,710,28),civilPlaceReason,civCaption);CText(new Rect(462,744,710,25),"E / R1 confirm   •   Q / R / L1 rotate   •   Circle cancel",civSmall);}
  if(civilFollow!=null&&civilFollowTime>0){CBox(new Rect(465,160,680,67),new Color(.02f,.07f,.1f,.96f));CText(new Rect(485,170,640,30),"AURORA / NATIVE ROCKET ASCENT",civBody,civCyan);CText(new Rect(486,202,640,25),"Altitude "+civilFollow.maxAltitude.ToString("F0")+" m / 1 km survey target / Circle returns",civSmall);}
 }
